import {makeTownListenButton, primeTownVoice, stopTownVoice} from './voicebank.js';
import {readAutoYarnCaptions, writeAutoYarnCaptions, shouldShowAutoYarnCaption} from './yarn-preferences.js';
// Lightweight, mobile-friendly conversation history and nearby subtitles.
// All captions are the precise text generated by TownLife when NPCs met.
// They are displayed as textContent so saved state cannot inject HTML.
export function mountTownYarns({life,player,onOpen=()=>{}}){
  const btn=document.createElement('button');
  btn.id='btn-town-yarns';btn.type='button';btn.textContent='🗣 Yarns';
  btn.title='Read what the residents are actually saying to each other';
  document.getElementById('btn-npcs').after(btn);
  let storage = null;
  try { storage = globalThis.localStorage; } catch { /* storage can be denied */ }
  const compact = globalThis.matchMedia?.('(max-width: 700px), (pointer: coarse)').matches ?? false;
  let autoCaptions = readAutoYarnCaptions(storage, compact);
  const settingsButton = document.createElement('button');
  settingsButton.id = 'btn-town-dialogue-settings';
  settingsButton.type = 'button';
  settingsButton.textContent = 'Dialogue settings';
  settingsButton.title = 'Turn automatic NPC conversation pop-ups on or off';
  settingsButton.setAttribute('aria-expanded', 'false');
  btn.after(settingsButton);

  const panel=document.createElement('section');
  panel.id='town-yarns';panel.hidden=true;
  panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','false');
  panel.setAttribute('aria-label','Town conversations');
  const head=document.createElement('header');
  const h=document.createElement('h2');h.textContent='🗣 Town conversations';
  const close=document.createElement('button');close.type='button';close.textContent='✕';
  close.setAttribute('aria-label','Close town conversations');head.append(h,close);
  const note=document.createElement('p');
  note.textContent='Actual resident encounters from the town simulation, not AI guesses. Newest first; conversations stay in your saved town.';
  const list=document.createElement('div');list.className='yarn-list';
  const detail=document.createElement('div');detail.className='yarn-detail';
  panel.append(head,note,list,detail);document.body.append(panel);

  const caption=document.createElement('div');
  caption.id='town-yarn-caption';caption.hidden=true;
  caption.setAttribute('role','status');
  const captionText=document.createElement('span');
  const expand=document.createElement('button');expand.type='button';expand.textContent='Read yarn';
  const captionDismiss = document.createElement('button');
  captionDismiss.type = 'button';
  captionDismiss.textContent = '✕';
  captionDismiss.setAttribute('aria-label', 'Dismiss nearby conversation');
  captionDismiss.title = 'Dismiss this conversation';
  caption.append(captionText,expand,captionDismiss);document.body.append(caption);

  const settingsPanel = document.createElement('section');
  settingsPanel.id = 'town-dialogue-settings';
  settingsPanel.hidden = true;
  settingsPanel.setAttribute('role', 'dialog');
  settingsPanel.setAttribute('aria-modal', 'false');
  settingsPanel.setAttribute('aria-label', 'Dialogue settings');
  const settingsHeading = document.createElement('header');
  const settingsTitle = document.createElement('h2');
  settingsTitle.textContent = 'Dialogue settings';
  const settingsClose = document.createElement('button');
  settingsClose.type = 'button';
  settingsClose.textContent = '✕';
  settingsClose.setAttribute('aria-label', 'Close dialogue settings');
  settingsHeading.append(settingsTitle,settingsClose);
  const autoLabel = document.createElement('label');
  autoLabel.className = 'town-yarn-toggle';
  const autoToggle = document.createElement('input');
  autoToggle.type = 'checkbox';
  autoToggle.id = 'town-auto-yarn-toggle';
  autoToggle.checked = autoCaptions;
  const labelText = document.createElement('span');
  labelText.textContent = 'Automatically show nearby conversations';
  autoLabel.append(autoToggle,labelText);
  const noteSettings = document.createElement('p');
  noteSettings.textContent = 'Off keeps the screen clear. You can still tap Yarns, NPCs or Ask AI to start conversations manually.';
  const saveNote = document.createElement('p');
  saveNote.id = 'town-dialogue-settings-status';
  saveNote.setAttribute('role', 'status');
  settingsPanel.append(settingsHeading,autoLabel,noteSettings,saveNote);
  document.body.append(settingsPanel);

  const style=document.createElement('style');
  style.textContent=`
#town-yarns{position:fixed;z-index:31;left:50%;bottom:max(12px,env(safe-area-inset-bottom));transform:translateX(-50%);background:#101d30f5;color:white;border:1px solid #7f9ab8;border-radius:14px;box-shadow:0 12px 40px #0008;padding:15px;width:min(580px,calc(100vw - 20px));max-height:75dvh;overflow-y:auto}
#town-yarns header{display:flex;align-items:center;justify-content:space-between;gap:12px}
#town-yarns h2{font-size:18px;margin:0}
#town-yarns p{font-size:12px;opacity:.83;margin:7px 0}
#town-yarns .yarn-list{display:flex;flex-wrap:wrap;gap:6px;padding:8px 0;max-height:23dvh;overflow-y:auto}
#town-yarns .yarn-list button{font-size:12px;max-width:100%;text-align:left}
#town-yarns .yarn-list button[aria-pressed="true"]{border-color:#7fe0ff;background:#295b79}
#town-yarns .yarn-line{padding:8px 10px;margin:7px 0;background:#213349;border-radius:9px}
#town-yarns .yarn-line b{color:#9ee8ff}
#town-yarns .yarn-line p{color:#fff;opacity:1;font-size:14px;margin:3px 0}
#town-yarns .yarn-when{color:#b5c7e0;font-size:12px}
#town-yarn-caption{position:fixed;z-index:12;left:50%;bottom:92px;transform:translateX(-50%);width:min(435px,calc(100vw - 24px));padding:10px 12px;border-radius:12px;background:#0d1a2de8;border:1px solid #9ac2de;color:white;text-align:center;box-shadow:0 5px 20px #0005;pointer-events:auto}
#town-yarn-caption span{display:block;margin-bottom:6px;line-height:1.35}
#town-yarn-caption button{padding:4px 9px;font-size:12px}
#town-dialogue-settings{position:fixed;z-index:32;left:50%;top:50%;transform:translate(-50%,-50%);width:min(440px,calc(100vw - 24px));max-height:85dvh;overflow:auto;background:#101d30f9;border:1px solid #9ac2de;color:white;border-radius:14px;padding:16px;box-shadow:0 12px 40px #0009}
#town-dialogue-settings header{display:flex;align-items:center;justify-content:space-between;gap:12px}
#town-dialogue-settings h2{font-size:19px;margin:0}
#town-dialogue-settings .town-yarn-toggle{display:flex;align-items:center;gap:12px;margin:18px 0 8px;font-size:15px;cursor:pointer}
#town-dialogue-settings input{width:22px;height:22px;flex:0 0 22px;accent-color:#88d8ff}
#town-dialogue-settings p{font-size:13px;line-height:1.5;opacity:.9}
#town-dialogue-settings button,#town-yarn-caption button{min-height:42px;min-width:42px;cursor:pointer}
#town-yarn-caption{display:flex;align-items:center;justify-content:center;gap:8px}
#town-yarn-caption[hidden],#town-yarns[hidden],#town-dialogue-settings[hidden]{display:none!important}
#town-yarn-caption span{flex:1;margin:0;text-align:left}
#town-yarn-caption [aria-label="Dismiss nearby conversation"]{flex-shrink:0}
body.playing #town-yarns,body.playing #town-yarn-caption,body.playing #town-dialogue-settings{display:none!important}
@media(max-width:700px){#town-yarns{max-height:69dvh;bottom:max(12px,env(safe-area-inset-bottom))}#town-yarn-caption{top:max(115px,calc(105px + env(safe-area-inset-top)));bottom:auto;width:min(360px,calc(100vw - 24px));max-height:25dvh;overflow:auto;font-size:12px;padding:6px 8px}#town-yarn-caption button{padding:6px;min-height:40px;min-width:40px}}
`;
  document.head.append(style);

  const entries=()=>life.social?.events?.filter(e=>Array.isArray(e.lines)&&e.lines.length===4)||[];
  const eventId=e=>e?[e.day,e.minute,e.kind,...e.people].join('|'):'';
  const time=e=>'Day '+e.day+' · '+String(Math.floor(e.minute/60)).padStart(2,'0')+':'+String(e.minute%60).padStart(2,'0');
  let chosen='',active=null,seconds=0,dismissedId='';
  let lastSeen=eventId(entries()[0]);
  const clear=element=>{while(element.firstChild)element.firstChild.remove();};
  function render(){
    const all=entries().slice(0,35);
    clear(list);clear(detail);
    if(!all.length){const empty=document.createElement('p');empty.textContent='No resident yarns yet. Let the town run, or head to the pub or café when neighbours are gathering.';detail.append(empty);return;}
    if(!all.some(e=>eventId(e)===chosen))chosen=eventId(all[0]);
    for(const e of all){
      const b=document.createElement('button');b.type='button';
      b.textContent=e.people.join(' & ')+' · '+(e.location||e.kind)+' · '+time(e);
      b.setAttribute('aria-pressed',String(eventId(e)===chosen));
      b.onclick=()=>{chosen=eventId(e);render();};list.append(b);
    }
    const e=all.find(x=>eventId(x)===chosen)||all[0];
    const when=document.createElement('div');when.className='yarn-when';
    when.textContent=e.people.join(' and ')+' · '+(e.location||e.kind)+' · '+time(e);
    detail.append(when);
    for(const line of e.lines){
      const box=document.createElement('div');box.className='yarn-line';
      const name=document.createElement('b');name.textContent=line.speaker;
      const text=document.createElement('p');text.textContent='“'+line.text+'”';
      box.append(name,text,makeTownListenButton(line.text));detail.append(box);
    }
  }
  function open(id){
    chosen=id||chosen;render();panel.hidden=false;caption.hidden=true;
    dismissedId = eventId(active);
    settingsPanel.hidden = true;
    settingsButton.setAttribute('aria-expanded', 'false');
    void primeTownVoice();
    btn.setAttribute('aria-expanded','true');onOpen();
    close.focus();
  }
  function dismiss(){stopTownVoice();panel.hidden=true;btn.setAttribute('aria-expanded','false');btn.focus();}
  btn.setAttribute('aria-expanded','false');
  btn.onclick=()=>panel.hidden?open():dismiss();
  close.onclick=dismiss;
  expand.onclick=()=>{if(active)open(eventId(active));};
  captionDismiss.onclick=()=>{dismissedId=eventId(active);caption.hidden=true;};
  function dismissSettings(){
    settingsPanel.hidden=true;
    settingsButton.setAttribute('aria-expanded','false');
    settingsButton.focus();
  }
  function openSettings(){
    if(!panel.hidden)dismiss();
    dismissedId=eventId(active);
    caption.hidden=true;
    settingsPanel.hidden=false;
    settingsButton.setAttribute('aria-expanded','true');
    onOpen();
    settingsClose.focus();
  }
  settingsButton.onclick=()=>settingsPanel.hidden?openSettings():dismissSettings();
  settingsClose.onclick=dismissSettings;
  autoToggle.onchange=()=>{
    autoCaptions=autoToggle.checked;
    if(!autoCaptions){dismissedId=eventId(active);caption.hidden=true;}
    const saved=writeAutoYarnCaptions(storage,autoCaptions);
    saveNote.textContent=saved?'Preference saved.':'Preference applies for this visit; browser storage is unavailable.';
  };
  function nearby(e,mode){
    if(mode==='house')return !!e.placeId&&e.placeId===life.playerAt;
    if(mode!=='town'||!e.position)return false;
    return Math.hypot(player.pos.x-e.position.x,player.pos.z-e.position.z)<=12;
  }
  function update(dt,mode){
    const e=entries()[0],id=eventId(e);
    if(id&&id!==lastSeen){
      lastSeen=id;active=e;seconds=0;
    }
    if(active)seconds+=Math.max(0,dt);
    const visible=shouldShowAutoYarnCaption({enabled:autoCaptions,activeId:eventId(active),dismissedId,elapsed:seconds,nearby:!!active&&nearby(active,mode),yarnPanelHidden:panel.hidden,settingsPanelHidden:settingsPanel.hidden});
    if(!visible){caption.hidden=true;return;}
    const i=Math.min(3,Math.floor(seconds/3.6)),line=active.lines[i];
    captionText.textContent=line.speaker+': “'+line.text+'”';
    caption.hidden=false;
  }
  return {update,isOpen:()=>!panel.hidden||!settingsPanel.hidden,close:()=>settingsPanel.hidden?dismiss():dismissSettings(),render};
}
